import{_ as n,C as r,o as s,c as i,j as a,a as d,E as c,a2 as l}from"./chunks/framework.DeW-aKVm.js";const b=JSON.parse('{"title":"A single home for the Nirantara docs","description":"The four Nirantara projects now share one documentation site, with raw Markdown and an LLM-friendly index for AI coding assistants.","frontmatter":{"title":"A single home for the Nirantara docs","description":"The four Nirantara projects now share one documentation site, with raw Markdown and an LLM-friendly index for AI coding assistants.","author":"vinaykumar","date":"2026-10-22T00:00:00.000Z","tags":["docs","announcement"],"outline":"deep","editLink":false},"headers":[],"relativePath":"blog/nirantara-docs-launch.md","filePath":"blog/nirantara-docs-launch.md"}'),h={name:"blog/nirantara-docs-launch.md"};function p(t,e,u,f,g,m){const o=r("AuthorCard");return s(),i("div",null,[e[0]||(e[0]=a("h1",{id:"a-single-home-for-the-nirantara-docs",tabindex:"-1"},[d("A single home for the Nirantara docs "),a("a",{class:"header-anchor",href:"#a-single-home-for-the-nirantara-docs","aria-label":'Permalink to "A single home for the Nirantara docs"'},"​")],-1)),c(o,{author:t.$frontmatter.author},null,8,["author"]),e[1]||(e[1]=l('<p>Nirantara builds four open-source projects: <code>k3sctl</code>, <code>mssql-mcp-go</code>, <code>postgres-mcp-go</code>, and <code>omniroute-operator</code>. Until now each project kept its documentation next to its code, which meant four different layouts and four different ways of finding the same kind of answer.</p><p>This site brings them together.</p><h2 id="what-changed" tabindex="-1">What changed <a class="header-anchor" href="#what-changed" aria-label="Permalink to &quot;What changed&quot;">​</a></h2><p>Every project now has the same structure: an overview, installation, configuration, and a reference section. The navigation mirrors the projects, so you can jump straight to the tool you are using instead of scanning a combined table of contents.</p><p>The content is still written per project. A page about <code>k3sctl</code> configuration does not explain MCP variables, and a page about T-SQL tooling does not explain Kubernetes operators. Sharing a site is not the same as merging the products.</p><h2 id="documentation-for-people-and-for-agents" tabindex="-1">Documentation for people and for agents <a class="header-anchor" href="#documentation-for-people-and-for-agents" aria-label="Permalink to &quot;Documentation for people and for agents&quot;">​</a></h2><p>Every page is available as raw Markdown by appending <code>.md</code> to its URL. The whole corpus is exported as:</p><ul><li><a href="/llms.txt">/llms.txt</a>: a curated index of every page with a one-line description.</li><li><a href="/llms-full.txt">/llms-full.txt</a>: the full text of every page in one file.</li></ul><p>There is also a compact <a href="/agents">map for coding agents</a> that lists where each project&#39;s documentation lives, plus the details that are easiest to get wrong when generating configuration. That page is deliberately short: it is a router, not a third copy of the reference.</p><h2 id="what-is-next" tabindex="-1">What is next <a class="header-anchor" href="#what-is-next" aria-label="Permalink to &quot;What is next&quot;">​</a></h2><p>The docs will keep moving with the projects. The blog is where release notes and design decisions will land as the tools change, starting with the posts below on <code>k3sctl</code>, the database MCP servers, and the OmniRoute operator.</p>',11))])}const x=n(h,[["render",p]]);export{b as __pageData,x as default};
